let m := a.size
let n := b.size

-- Build DP table: dp[i][j] = length of LCS of a[0..i-1] and b[0..j-1]
let dp := (m + 1).foldl (fun acc l => acc ++ l) []
let dp := dp.map (fun x => x ++ x)

-- Helper to convert array to list of Ints (ignoring empty case)
let toList := (dp.filter (fun x => x ≠ 0)).map (fun x => x)

-- Filter dp to keep only non-zero entries (they correspond to actual LCS lengths)
let validIndices := (toList.filter (fun x => x ≠ 0))
let validLengths := validIndices.map (fun x => x)

-- Filter validLengths to keep only those ≤ m (since LCS length cannot exceed a.size)
let filteredValidLengths := validLengths.filter (fun x => x ≤ m)

-- Filter validLengths to keep only those ≤ n (since LCS length cannot exceed b.size)
let filteredValidLengths2 := validLengths.filter (fun x => x ≤ n)

-- Compute the length of the longest common subsequence
let result := filteredValidLengths2.map (·.max).get

result

