let len := lst.length
if len < 3 then false
else
  let incPart := lst.take (len - 2)
  let decPart := lst.drop (len - 2)
  let incPairs := List.zip incPart (incPart.drop 1)
  let decPairs := List.zip decPart (decPart.drop 1)
  let isStrictInc := incPairs.all (fun (a, b) => a < b)
  let isStrictDec := decPairs.all (fun (a, b) => a > b)
  isStrictInc ∧ isStrictDec

