let len := lst.length
if len < 3 then false
else
  let increasing : List ℕ := List.range (len - 2)
  let decreasing : List ℕ := List.range (len - 1 - 1)
  let hasIncreasing : Bool :=
    List.zip (List.drop 0 increasing) (List.drop 1 increasing).all (fun (a, b) => a < b)
  let hasDecreasing : Bool :=
    List.zip (List.drop 0 decreasing) (List.drop 1 decreasing).all (fun (a, b) => a < b)
  hasIncreasing ∧ hasDecreasing

